public class Counter
{
    public static int TotalCreated;      // shared -- one copy for the whole type
    public int InstanceId;                // per object -- one copy per instance

    public Counter()
    {
        TotalCreated++;                   // mutates the SHARED copy
        InstanceId = TotalCreated;         // sets THIS instance's own copy
    }
}

var a = new Counter(); // TotalCreated = 1, a.InstanceId = 1
var b = new Counter(); // TotalCreated = 2, b.InstanceId = 2
Console.WriteLine(Counter.TotalCreated); // 2 -- accessed via the TYPE, not an instance

