public abstract class OrderProcessor
{
    public void Process(Order o)              // the fixed sequence -- never overridden
    {
        Validate(o);
        CalculateTotal(o);                     // <- varies per subclass
        SaveToDb(o);
        SendConfirmation(o);
    }

    protected virtual void Validate(Order o) { if (o.Items.Count == 0) throw new InvalidOperationException(); }
    protected abstract void CalculateTotal(Order o);   // mandatory customization point
    protected virtual void SaveToDb(Order o) => Console.WriteLine("Saved");
    protected virtual void SendConfirmation(Order o) => Console.WriteLine("Confirmed");
}

public class ExportOrder : OrderProcessor
{
    protected override void CalculateTotal(Order o) => o.Total = o.Subtotal + o.Freight;
}

public class DomesticOrder : OrderProcessor
{
    protected override void CalculateTotal(Order o) => o.Total = o.Subtotal * 1.18m; // + local tax
}

public class Downloader
