public class Money
{
    public decimal Amount { get; }
    public Money(decimal amount) => Amount = amount;

    public static implicit operator decimal(Money m) => m.Amount;         // safe -- never loses data
    public static explicit operator Money(decimal d) => new Money(d);    // deliberate -- requires a cast
}

